import sys
import argparse
import re
from xml.etree import ElementTree as ET

def parse_rules(xml_path):
    try:
        tree = ET.parse(xml_path)
        root = tree.getroot()
        rules = []
        for rule in root.findall('rule'):
            name = rule.get('name')
            if not name:
                print(f"config error: missing 'name' attribute in rule", file=sys.stderr)
                sys.exit(2)
            pattern = rule.text
            if not pattern:
                print(f"config error: empty rule text", file=sys.stderr)
                sys.exit(2)
            try:
                compiled = re.compile(pattern)
            except re.error:
                print(f"<rule name=\"{name}\">: invalid regex", file=sys.stderr)
                continue
            rules.append((name, compiled))
        return rules
    except ET.ParseError as e:
        print(f"config error: {str(e)}", file=sys.stderr)
        sys.exit(2)

def process_log(rules, log_path):
    try:
        with open(log_path, 'r') as f:
            for line in f:
                for name, pattern in rules:
                    if pattern.search(line.rstrip('\n')):
                        print(f"{name}\t{line.rstrip('\n')}")
                        break
    except IOError as e:
        print(f"log error: {str(e)}", file=sys.stderr)
        sys.exit(1)

def main():
    parser = argparse.ArgumentParser(description='Filter log lines based on XML rules.')
    parser.add_argument('rules_file', type=str, help='Path to XML rules file')
    parser.add_argument('log_file', type=str, help='Path to log file')
    args = parser.parse_args()

    rules = parse_rules(args.rules_file)
    process_log(rules, args.log_file)

if __name__ == "__main__":
    main()
